    public static int itCompare(emon.Port.Cells out, byte[] b, int from, int to, int exact) {
        // -1 when `out` matches the hex in b[from, to): exactly, or (exact =
        // 0) as a PREFIX of it. -2 for a length problem; otherwise the
        // index of the first differing byte.
        int n = (to - from) / 2;
        int i = 0;
        if (emon.Port.cellsLen(out) > n) {
            return -2;
        }
        if ((exact == 1) && (emon.Port.cellsLen(out) != n)) {
            return -2;
        }
        while (i < emon.Port.cellsLen(out)) {
            if (emon.Port.cellsAt(out, i) != ((itHexval(emon.Port.blobU8(b, from + (i * 2))) * 16) + itHexval(emon.Port.blobU8(b, from + ((i * 2) + 1))))) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
